            --slide-padding: clamp(1rem, 3.5vw, 3.5rem);
            --content-gap: clamp(0.5rem, 1.5vw, 1.5rem);
        }

        /* === BASE RESET === */
        * { margin: 0; padding: 0; box-sizing: border-box; }
        html, body { height: 100%; width: 100%; overflow: hidden; }
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* ===========================================
           HORIZONTAL SCROLL CONTAINER
           Slides are arranged side-by-side, scrolling left/right
           =========================================== */
        .slides-container {
            display: flex;
            width: 100%;
            height: 100vh;
            overflow-x: auto;
            overflow-y: hidden;
            scroll-snap-type: x mandatory;
            scroll-behavior: smooth;
        }
        /* Hide scrollbar */
        .slides-container::-webkit-scrollbar { display: none; }
        .slides-container { -ms-overflow-style: none; scrollbar-width: none; }

        /* ===========================================
           SLIDE BASE
           Each slide fills the viewport exactly
           =========================================== */
        .slide {
            min-width: 100vw;
            width: 100vw;
            height: 100vh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
            flex-shrink: 0;
        }

        /* === BACKGROUND PATTERN === */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.015) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.015) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }
        .slide > * { position: relative; z-index: 1; }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1, h2, h3 { font-family: var(--font-display); }
        h1 { font-size: var(--title-size); font-weight: 800; line-height: 1.1; }
        h2 { font-size: var(--h2-size); font-weight: 700; line-height: 1.25; }
        h3 { font-size: var(--h3-size); font-weight: 600; line-height: 1.3; }

        /* ===========================================
           LAYOUT HELPERS
           =========================================== */
        .slide-inner {
            padding: var(--slide-padding);
            flex: 1;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            min-height: 0;
        }
        .slide-header {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            margin-bottom: var(--content-gap);
            flex-shrink: 0;
        }
        .slide-number {
            font-family: var(--font-display);
            font-size: clamp(0.65rem, 1.2vw, 0.95rem);
            font-weight: 800;
            color: var(--accent);
            letter-spacing: 0.08em;
            flex-shrink: 0;
            padding-top: 0.25em;
        }
        .slide-body { flex: 1; overflow: hidden; min-height: 0; }
        .slide-footer {
            font-size: var(--small-size);
            color: var(--text-secondary);
            flex-shrink: 0;
            padding: clamp(0.2rem, 0.4vw, 0.4rem) var(--slide-padding);
        }

        /* === TWO COLUMN LAYOUT === */
        .two-col {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 2vw, 2rem);
            height: 100%;
            align-items: start;
        }
        .two-col-2-3 { grid-template-columns: 2fr 3fr; }
        .two-col-3-2 { grid-template-columns: 3fr 2fr; }

        /* ===========================================
           STAT CARDS
           =========================================== */
        .stat-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
        }
        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vw, 1rem);
        }
        .stat-value {
            font-family: var(--font-display);
            font-size: clamp(1.1rem, 2.2vw, 1.8rem);
            font-weight: 800;
            color: var(--accent);
            line-height: 1.1;
        }
        .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.2em;
        }

        /* ===========================================
           HORIZONTAL BAR CHART
           =========================================== */
        .bar-chart { display: flex; flex-direction: column; gap: clamp(2px, 0.35vw, 5px); }
        .bar-row { display: flex; align-items: center; gap: clamp(0.3rem, 0.6vw, 0.6rem); }
        .bar-label {
            font-size: clamp(0.55rem, 0.85vw, 0.75rem);
            color: var(--text-secondary);
            width: clamp(70px, 10vw, 120px);
            text-align: right;
            flex-shrink: 0;
            white-space: nowrap;
        }
        .bar-track {
            flex: 1;
            height: clamp(12px, 1.8vh, 22px);
            background: rgba(255,255,255,0.03);
            border-radius: 3px;
            overflow: hidden;
        }
        .bar-fill {
            height: 100%;
            border-radius: 3px;
            background: var(--accent);
        }
        .bar-value {
            font-size: clamp(0.55rem, 0.85vw, 0.75rem);
            font-weight: 600;
            width: clamp(45px, 6vw, 70px);
            flex-shrink: 0;
            color: var(--text-primary);
        }

        /* ===========================================
           EMPLOYMENT BAR (grouped global vs US)
           =========================================== */
        .emp-row {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 0.6vw, 0.5rem);
            margin: clamp(1px, 0.2vw, 3px) 0;
        }
        .emp-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            width: clamp(65px, 9vw, 100px);
            text-align: right;
            flex-shrink: 0;
        }
        .emp-bar-track {
            flex: 1;
            height: clamp(12px, 1.6vh, 20px);
            background: rgba(255,255,255,0.03);
            border-radius: 3px;
            overflow: hidden;
            position: relative;
        }
        .emp-bar-global {
            height: 100%;
            border-radius: 3px;
            background: var(--accent);
            opacity: 0.6;
        }
        .emp-bar-us {
            position: absolute;
            top: 0; left: 0;
            height: 100%;
            border-radius: 3px;
            background: var(--accent-warm);
        }
        .emp-pct {
            font-size: var(--small-size);
            width: clamp(35px, 4.5vw, 50px);
            flex-shrink: 0;
        }

        /* ===========================================
           TREND CHART (stacked bars)
           =========================================== */
        .trend-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vw, 0.9rem);
        }
        .trend-year-group { display: flex; flex-direction: column; gap: clamp(1px, 0.2vw, 3px); }
        .trend-year-label {
            font-family: var(--font-display);
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--text-secondary);
        }
        .trend-bars {
            display: flex;
            height: clamp(18px, 2.8vh, 30px);
            border-radius: 4px;
            overflow: hidden;
        }
        .trend-segment {
            height: 100%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: clamp(0.5rem, 0.75vw, 0.65rem);
            font-weight: 600;
            color: rgba(0,0,0,0.75);
            min-width: 0;
            overflow: hidden;
        }

        /* ===========================================
           COMPANY SIZE GRID
           =========================================== */
        .size-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.25rem, 0.5vw, 0.4rem);
        }
        .size-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: clamp(0.3rem, 0.6vw, 0.5rem);
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 5px;
        }
        .size-pct {
            font-family: var(--font-display);
            font-size: clamp(0.75rem, 1.3vw, 1.1rem);
            font-weight: 700;
            color: var(--accent);
        }
        .size-label {
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-secondary);
            text-align: center;
        }

        /* ===========================================
           CALLOUT BOXES
           =========================================== */
        .callout {
            background: var(--bg-card);
            border-left: 3px solid var(--accent);
            padding: clamp(0.35rem, 0.8vw, 0.7rem) clamp(0.5rem, 1vw, 0.9rem);
            border-radius: 0 6px 6px 0;
            margin: clamp(0.25rem, 0.6vw, 0.5rem) 0;
        }
        .callout-warm { border-left-color: var(--accent-warm); }
        .callout-gold { border-left-color: var(--accent-gold); }
        .callout-red { border-left-color: var(--accent-red); }
        .callout-title {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 0.15em;
        }
        .callout-body {
            font-size: var(--body-size);
            line-height: 1.4;
        }

        /* ===========================================
           IMAGE STYLES
           =========================================== */
        .chart-img-wrap {
            background: #ffffff;
            border-radius: 8px;
            padding: clamp(4px, 0.5vw, 8px);
            display: flex;
            align-items: center;
            justify-content: center;
            flex: 1;
            min-height: 0;
        }
        .chart-img {
            max-width: 100%;
            max-height: min(55vh, 480px);
            object-fit: contain;
            border-radius: 4px;
        }
        .chart-caption {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: clamp(0.15rem, 0.3vw, 0.3em);
            text-align: center;
        }

        /* ===========================================
           TAKEAWAY ITEMS
           =========================================== */
        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.4rem, 0.8vw, 0.7rem);
            padding: clamp(0.35rem, 0.7vw, 0.6rem) 0;
            border-bottom: 1px solid var(--border-subtle);
        }
        .takeaway-item:last-child { border-bottom: none; }
        .takeaway-num {
            font-family: var(--font-display);
            font-size: clamp(0.8rem, 1.3vw, 1.15rem);
            font-weight: 800;
            color: var(--accent);
            flex-shrink: 0;
            line-height: 1.1;
        }
        .takeaway-text {
            font-size: var(--body-size);
            line-height: 1.45;
        }
        .hl { color: var(--accent); font-weight: 600; }
        .hl-warm { color: var(--accent-warm); font-weight: 600; }
        .hl-gold { color: var(--accent-gold); font-weight: 600; }

        /* ===========================================
           LEGEND
           =========================================== */
        .legend {
            display: flex;
            gap: clamp(0.5rem, 1.2vw, 1.2rem);
            margin-top: clamp(0.3rem, 0.5vw, 0.5rem);
        }
        .legend-item {
            display: flex;
            align-items: center;
            gap: clamp(0.15rem, 0.3vw, 0.3rem);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }
        .legend-dot { width: 10px; height: 10px; border-radius: 2px; flex-shrink: 0; }

        /* ===========================================
           TITLE SLIDE
           =========================================== */
        .title-slide {
            justify-content: center;
            align-items: center;
            text-align: center;
        }
        .accent-line {
            width: 60px;
            height: 4px;
            background: var(--accent);
            margin: clamp(0.5rem, 1.5vw, 1.5rem) auto;
        }
        .title-subtitle {
            font-size: var(--h3-size);
            color: var(--text-secondary);
        }
        .title-stats {
            display: flex;
            gap: clamp(1.5rem, 4vw, 4rem);
            margin-top: clamp(1rem, 2.5vw, 2.5rem);
        }
        .title-stat-value {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 3.5vw, 2.8rem);
            font-weight: 800;
            color: var(--accent);
        }
        .title-stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.1em;
        }
        .title-source {
            position: absolute;
            bottom: var(--slide-padding);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           GLOW ACCENTS
           =========================================== */
        .glow {
            position: absolute;
            border-radius: 50%;
            filter: blur(120px);
            opacity: 0.12;
            pointer-events: none;
            z-index: 0;
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 1000;
            transition: width 0.3s;
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 1vw, 1rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 1000;
        }
        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255,255,255,0.15);
            cursor: pointer;
            transition: all 0.3s;
        }
        .nav-dot.active {
            background: var(--accent);
            box-shadow: 0 0 8px rgba(0,229,160,0.5);
        }

        /* ===========================================
           RESPONSIVE
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.35rem, 1vw, 0.8rem);
            }
        }
        @media (max-height: 600px) {
            :root { --slide-padding: clamp(0.5rem, 2vw, 1rem); }
            .nav-dots, .progress-bar { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 1.5vw, 0.8rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.6rem, 1vw, 0.8rem);
            }
            .nav-dots, .progress-bar, .decorative { display: none; }
        }

        /* ===========================================
           REDUCED MOTION
           =========================================== */
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
        }
    </style>
</head>
