    <script>
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.container = document.getElementById('slidesContainer');
                this.currentSlide = 0;
                this.setupKeyboardNav();
                this.setupTouchNav();
                this.setupContainerScroll();
                this.setupProgressBar();
                this.setupNavDots();
            }

            setupContainerScroll() {
                this.container.addEventListener('scroll', () => {
                    const scrollLeft = this.container.scrollLeft;
                    const slideWidth = window.innerWidth;
                    const newSlide = Math.round(scrollLeft / slideWidth);
                    if (newSlide !== this.currentSlide) {
                        this.currentSlide = newSlide;
                        this.updateProgress();
                        this.updateNavDots();
                    }
                });
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    }
                });
            }

            setupTouchNav() {
                let touchStartX = 0;
                document.addEventListener('touchstart', (e) => { touchStartX = e.touches[0].clientX; });
                document.addEventListener('touchend', (e) => {
                    const diff = touchStartX - e.changedTouches[0].clientX;
                    if (Math.abs(diff) > 50) {
                        this.goToSlide(this.currentSlide + (diff > 0 ? 1 : -1));
                    }
                });
            }

            setupProgressBar() {
                const bar = document.getElementById('progressBar');
                if (!bar) return;
                this.updateProgress = () => {
                    const pct = ((this.currentSlide + 1) / this.slides.length) * 100;
                    bar.style.width = pct + '%';
                };
                this.updateProgress();
            }

            setupNavDots() {
                const nav = document.getElementById('navDots');
                if (!nav) return;
                this.slides.forEach((_, i) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (i === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(i));
                    nav.appendChild(dot);
                });
                this.updateNavDots = () => {
                    nav.querySelectorAll('.nav-dot').forEach((d, i) => {
                        d.classList.toggle('active', i === this.currentSlide);
                    });
                };
            }

            goToSlide(index) {
                if (index < 0 || index >= this.slides.length) return;
                this.currentSlide = index;
                const slideWidth = window.innerWidth;
                this.container.scrollTo({
                    left: index * slideWidth,
                    top: 0,
                    behavior: 'instant'
                });
                this.updateProgress();
                this.updateNavDots();
            }
        }

        new SlidePresentation();
    </script>
