#!/usr/bin/env python3
"""Custom HTML-to-PPTX converter that scrolls directly via JavaScript evaluate."""

import os
import http.server
import subprocess
import sys
import tempfile
import threading
from pathlib import Path

from PIL import Image
from pptx import Presentation
from pptx.util import Emu


def _start_http_server(directory: Path, port: int = 0):
    handler = http.server.SimpleHTTPRequestHandler
    server = http.server.HTTPServer(
        ("127.0.0.1", port),
        lambda *a, **kw: handler(*a, directory=str(directory), **kw),
    )
    actual_port = server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server, actual_port


def _make_capture_script(url: str, out_dir: str, width: int, height: int, slide_count: int) -> str:
    return f"""\
const {{ chromium }} = require('playwright');

(async () => {{
    const browser = await chromium.launch({{ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined }});
    const page = await browser.newPage();
    await page.setViewportSize({{ width: {width}, height: {height} }});
    await page.goto('{url}', {{ waitUntil: 'networkidle' }});
    await page.waitForTimeout(800);

    // Screenshot slide 1 (already visible)
    await page.screenshot({{ path: `{out_dir}/slide_001.png` }});

    for (let i = 1; i < {slide_count}; i++) {{
        // Use evaluate to directly scroll the container
        await page.evaluate((idx) => {{
            const container = document.getElementById('slidesContainer');
            if (container) {{
                container.scrollTo({{ left: idx * window.innerWidth, behavior: 'instant' }});
            }}
        }}, i);
        await page.waitForTimeout(400);
        const idx = String(i + 1).padStart(3, '0');
        await page.screenshot({{ path: `{out_dir}/slide_${{idx}}.png` }});
    }}

    console.log(JSON.stringify({{ captured: {slide_count} }}));
    await browser.close();
}})();
"""


def _deduplicate_slides(image_dir: Path) -> list[Path]:
    pngs = sorted(image_dir.glob("slide_*.png"))
    if len(pngs) <= 1:
        return pngs
    unique: list[Path] = [pngs[0]]
    prev_img = Image.open(pngs[0])
    for png in pngs[1:]:
        curr_img = Image.open(png)
        is_dup = True
        for x_frac in (0.25, 0.5, 0.75):
            for y_frac in (0.25, 0.5, 0.75):
                px = int(curr_img.width * x_frac)
                py = int(curr_img.height * y_frac)
                if curr_img.getpixel((px, py)) != prev_img.getpixel((px, py)):
                    is_dup = False
                    break
            if not is_dup:
                break
        if not is_dup:
            unique.append(png)
            prev_img = curr_img
        else:
            break
    return unique


def assemble_pptx(slide_images: list[Path], output_path: Path) -> None:
    prs = Presentation()
    prs.slide_width = Emu(12192000)
    prs.slide_height = Emu(6858000)
    blank_layout = prs.slide_layouts[6]
    for img_path in slide_images:
        slide = prs.slides.add_slide(blank_layout)
        slide.shapes.add_picture(
            str(img_path), left=Emu(0), top=Emu(0),
            width=prs.slide_width, height=prs.slide_height,
        )
    prs.save(str(output_path))


def main():
    html_path = Path("/app/benchmark/presentation.html").resolve()
    output_path = Path("/app/output/final_deck.pptx").resolve()
    width, height = 1920, 1080
    slide_count = 8

    serve_dir = html_path.resolve().parent
    server, port = _start_http_server(serve_dir)
    url = f"http://127.0.0.1:{port}/{html_path.resolve().name}"

    try:
        with tempfile.TemporaryDirectory(prefix="slides_") as tmp:
            tmp_dir = Path(tmp)
            script = _make_capture_script(url, str(tmp_dir), width, height, slide_count)
            script_file = tmp_dir / "_capture.cjs"
            script_file.write_text(script)

            env = os.environ.copy()
            env.setdefault("NODE_PATH", "/usr/local/lib/node_modules:/app/node_modules")
            env.setdefault("PLAYWRIGHT_BROWSERS_PATH", "/root/.cache/ms-playwright")
            env.setdefault("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")

            result = subprocess.run(
                ["node", str(script_file)],
                capture_output=True, text=True, timeout=180, env=env,
            )
            if result.returncode != 0:
                print(f"Playwright stderr:\n{result.stderr}", file=sys.stderr)
                raise RuntimeError(f"Screenshot script failed (exit {result.returncode})")
            print(f"Playwright stdout: {result.stdout}")
    finally:
        server.shutdown()

    images = _deduplicate_slides(Path(tmp_dir))
    print(f"Captured {len(images)} unique slide(s), assembling PPTX ...")
    assemble_pptx(images, output_path)
    print(f"Done -> {output_path}")


if __name__ == "__main__":
    main()

